package com.library.service;
import com.library.dao.*; import com.library.enums.Role; import com.library.exception.*; import com.library.model.*; import com.library.session.SessionManager; import com.library.util.*; import java.math.*; import java.sql.*; import java.time.LocalDate; import java.util.*;
public class LibraryService { private final BookDAO books=new BookDAO(); private final UserDAO users=new UserDAO(); private final TransactionDAO transactions=new TransactionDAO(); private void admin(){if(!SessionManager.hasRole(Role.ADMIN))throw new AuthorizationException("Admin access required.");} public void issue(long memberId,long bookId){issue(memberId,bookId,DateUtil.LOAN_DAYS);} public void issue(long memberId,long bookId,int loanDays){admin();Member m=users.findMember(memberId);if(m==null)throw new MemberNotFoundException("Member not found.");if(!"ACTIVE".equals(m.getStatus()))throw new LibraryException("The member account is inactive.");Book b=books.findById(bookId);if(b==null)throw new BookNotFoundException("Book not found.");if(!"ACTIVE".equals(b.getStatus())||b.getAvailableQuantity()<1)throw new BookUnavailableException("This book is unavailable.");try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{if(transactions.activeCount(c,memberId)>=3)throw new LibraryException("A member may borrow at most 3 books.");if(transactions.hasActiveBook(c,memberId,bookId))throw new LibraryException("This member already has this book issued.");Transaction t=new Transaction();t.setBookId(bookId);t.setMemberId(memberId);t.setIssueDate(LocalDate.now());t.setDueDate(DateUtil.dueDate(t.getIssueDate(),loanDays));transactions.insert(c,t);books.changeAvailability(c,bookId,-1);c.commit();}catch(Exception e){c.rollback();if(e instanceof LibraryException)throw (LibraryException)e;throw new LibraryException("Unable to issue book.",e);}}catch(SQLException e){throw new LibraryException("Unable to issue book.",e);}}
 public BigDecimal returnBook(long transactionId){admin();Transaction t=transactions.findById(transactionId);if(t==null)throw new LibraryException("Transaction not found.");if(t.getReturnDate()!=null)throw new LibraryException("This book was already returned.");LocalDate returned=LocalDate.now();BigDecimal fine=BigDecimal.valueOf(DateUtil.lateDays(t.getDueDate(),returned)*DateUtil.FINE_PER_DAY);try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{transactions.returnBook(c,transactionId,java.sql.Date.valueOf(returned),fine);books.changeAvailability(c,t.getBookId(),1);c.commit();return fine;}catch(Exception e){c.rollback();throw new LibraryException("Unable to return book.",e);}}catch(SQLException e){throw new LibraryException("Unable to return book.",e);}}
 public List<Transaction> transactions(String term){admin();transactions.refreshOverdue();return transactions.findAll(term==null?"":term);} public List<Transaction> myTransactions(long memberId){if(!SessionManager.hasRole(Role.ADMIN)&&(!(SessionManager.getCurrentUser() instanceof Member)||((Member)SessionManager.getCurrentUser()).getMemberId()!=memberId))throw new AuthorizationException("You may only view your own borrowing history.");transactions.refreshOverdue();return transactions.findByMember(memberId);} }
